/**
 * @summary Get outbound notification settings
 */
export const getNotificationSettingsResponseRepeatHoursMax = 168;

export const getNotificationSettingsResponseTempRepeatHoursMax = 168;

export const getNotificationSettingsResponseDryHopRepeatHoursMax = 168;

export const GetNotificationSettingsResponse = zod
  .object({
    channel: zod
      .enum(["none", "ntfy", "webhook"])
      .describe("none disables notifications entirely."),
    ntfyServer: zod
      .string()
      .describe("Base URL of the ntfy server. Defaults to https://ntfy.sh."),
    ntfyTopic: zod
      .string()
      .describe(
        "ntfy topic to publish to. Treat as a secret — anyone who knows it can read your alerts.",
      ),
    webhookUrl: zod
      .string()
      .describe(
        "URL to POST a JSON payload to. Also covers Discord and Slack incoming webhooks.",
      ),
    types: zod
      .array(
        zod.enum([
          "temp_out_of_range",
          "gravity_stalled",
          "device_offline",
          "battery_low",
        ]),
      )
      .describe("Which alert types should notify."),
    repeatHours: zod
      .int()
      .min(1)
      .max(getNotificationSettingsResponseRepeatHoursMax)
      .describe(
        "Minimum hours between repeat notifications while a condition stays active.",
      ),
    tempRepeatHours: zod
      .int()
      .min(1)
      .max(getNotificationSettingsResponseTempRepeatHoursMax)
      .nullish()
      .describe(
        "Overrides repeatHours for temp_out_of_range only. Null inherits it, which is the default. A temperature excursion is actionable straight away, so it often warrants a shorter interval than the rest.",
      ),
    boilAlerts: zod
      .boolean()
      .optional()
      .describe(
        "Notify at each hop addition and at flameout while a boil timer is running. Kept out of types because it is a one-shot schedule, not a monitored condition, and so an existing saved types list does not leave it switched off on upgrade. Defaults to true.",
      ),
    dryHopAlerts: zod
      .boolean()
      .optional()
      .describe(
        "Remind when a dry hop addition comes due during conditioning, and keep reminding every dryHopRepeatHours until it is marked added. Kept out of types for the same reason as boilAlerts. Defaults to true.",
      ),
    dryHopRepeatHours: zod
      .int()
      .min(1)
      .max(getNotificationSettingsResponseDryHopRepeatHoursMax)
      .optional()
      .describe(
        "Hours between dry hop reminders while an addition is still due. Defaults to 6.",
      ),
    autoAdvanceAlerts: zod
      .boolean()
      .optional()
      .describe(
        "Notify once when a batch is moved to Conditioning automatically. Kept out of types for the same reason as boilAlerts. Defaults to true.",
      ),
  })
  .describe(
    "Outbound notification config. Both channels are plain outbound POSTs, so they work on a plain-HTTP LAN deployment with no certificates.",
  );

